using Microsoft.EntityFrameworkCore;
using SancMeld.Core.Domain;

namespace SancMeld.Core.Data;

/// <summary>
/// The schema is defined here and generated by EF Core migrations:
///
///   dotnet ef migrations add &lt;Name&gt; --project src/SancMeld.Core --startup-project src/SancMeld.Server
///   dotnet ef database update       --project src/SancMeld.Core --startup-project src/SancMeld.Server
///
/// A few PostgreSQL features have no first-class EF mapping and are emitted as
/// raw SQL inside the migration: the sm_normalize_name() function and the
/// designation_current view. They are marked in the migration.
///
/// This context is deliberately TENANT-UNAWARE. The hosted edition adds
/// multi-tenancy in its own migration set as an additive change — a tenant_id
/// column defaulted from a session setting, plus RLS policies — so nothing here
/// has to change and there is only ever one core schema.
/// </summary>
public class SancMeldDbContext(DbContextOptions<SancMeldDbContext> options) : DbContext(options)
{
    public DbSet<Jurisdiction> Jurisdictions => Set<Jurisdiction>();
    public DbSet<SanctionsSource> Sources => Set<SanctionsSource>();
    public DbSet<ImportRun> ImportRuns => Set<ImportRun>();
    public DbSet<SourceSnapshot> Snapshots => Set<SourceSnapshot>();
    public DbSet<ImportStagingRecord> ImportStaging => Set<ImportStagingRecord>();

    public DbSet<Designation> Designations => Set<Designation>();
    public DbSet<DesignationName> Names => Set<DesignationName>();
    public DbSet<DesignationBirth> Births => Set<DesignationBirth>();
    public DbSet<DesignationIdentifier> Identifiers => Set<DesignationIdentifier>();
    public DbSet<DesignationAddress> Addresses => Set<DesignationAddress>();
    public DbSet<DesignationNationality> Nationalities => Set<DesignationNationality>();
    public DbSet<DesignationMeasure> Measures => Set<DesignationMeasure>();
    public DbSet<DesignationXref> CrossReferences => Set<DesignationXref>();
    public DbSet<SanctionProgramme> Programmes => Set<SanctionProgramme>();
    public DbSet<LegalInstrument> LegalInstruments => Set<LegalInstrument>();
    public DbSet<DesignationProgramme> DesignationProgrammes => Set<DesignationProgramme>();
    public DbSet<DesignationLegalInstrument> DesignationLegalInstruments => Set<DesignationLegalInstrument>();

    public DbSet<CanonicalSubject> CanonicalSubjects => Set<CanonicalSubject>();
    public DbSet<SubjectDesignationLink> SubjectLinks => Set<SubjectDesignationLink>();

    public DbSet<MatchAlgorithm> MatchAlgorithms => Set<MatchAlgorithm>();
    public DbSet<ScreeningRequest> ScreeningRequests => Set<ScreeningRequest>();
    public DbSet<ScreeningCandidate> ScreeningCandidates => Set<ScreeningCandidate>();
    public DbSet<AdjudicationReason> AdjudicationReasons => Set<AdjudicationReason>();
    public DbSet<Adjudication> Adjudications => Set<Adjudication>();
    public DbSet<TrainingSample> TrainingSamples => Set<TrainingSample>();

    public DbSet<EmbeddingModel> EmbeddingModels => Set<EmbeddingModel>();
    public DbSet<DesignationNameEmbedding> NameEmbeddings => Set<DesignationNameEmbedding>();

    public DbSet<Admin> Admins => Set<Admin>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.HasPostgresExtension("pg_trgm")        // trigram similarity + GIN index
         .HasPostgresExtension("unaccent")       // diacritics removal
         .HasPostgresExtension("fuzzystrmatch")  // levenshtein, dmetaphone
         .HasPostgresExtension("pgcrypto");      // gen_random_uuid()

        b.Entity<Jurisdiction>(e =>
        {
            e.ToTable("jurisdiction");
            e.HasIndex(x => x.Code).IsUnique();
            e.Property(x => x.Iso2).HasMaxLength(2);

            e.HasData(
                new Jurisdiction
                {
                    Id = WellKnownIds.EuJurisdiction,
                    Code = "EU",
                    Name = "European Union",
                    Kind = "EU",
                    ResearchStatus = "CONFIRMED",
                    ResearchEvidenceUrl = "https://data.europa.eu/data/datasets/consolidated-list-of-persons-groups-and-entities-subject-to-eu-financial-sanctions",
                },
                new Jurisdiction
                {
                    Id = WellKnownIds.UnJurisdiction,
                    Code = "UN",
                    Name = "United Nations Security Council",
                    Kind = "UN",
                    ResearchStatus = "CONFIRMED",
                    ResearchEvidenceUrl = "https://www.un.org/securitycouncil/content/un-sc-consolidated-list",
                });
        });

        b.Entity<SanctionsSource>(e =>
        {
            e.ToTable("sanctions_source");
            e.HasIndex(x => x.Code).IsUnique();
            e.HasOne(x => x.Jurisdiction).WithMany(x => x.Sources).HasForeignKey(x => x.JurisdictionId);
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");
            e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()");

            // Seeded rather than left to the operator: a source row is what an import run,
            // a snapshot and every designation hang off, so a fresh database that cannot
            // import anything until someone hand-writes a UUID is not a usable one.
            e.HasData(new SanctionsSource
            {
                Id = WellKnownIds.EuFsfSource,
                JurisdictionId = WellKnownIds.EuJurisdiction,
                Code = "EU_FSF",
                Name = "EU Consolidated Financial Sanctions List",
                Publisher = "European Commission",
                LegalEffect = LegalEffect.Binding,
                Format = "XML",
                LandingPageUrl = "https://data.europa.eu/data/datasets/consolidated-list-of-persons-groups-and-entities-subject-to-eu-financial-sanctions",
                RequiresUserAgent = true,
                IsActive = true,
                ParserKey = "EU_FSF",

                // The list is republished irregularly and the connector detects that from
                // a 3.9 kB feed, so checking daily costs almost nothing.
                CronExpression = "0 4 * * *",
                MinExpectedRecords = 4000,
                CreatedAt = WellKnownIds.SeededAt,
                UpdatedAt = WellKnownIds.SeededAt,
            });

            // Adding a source is a row, not a code change: the scheduler reads its jobs
            // from this table, so this seed is also what creates the recurring import.
            e.HasData(new SanctionsSource
            {
                Id = WellKnownIds.UnScSource,
                JurisdictionId = WellKnownIds.UnJurisdiction,
                Code = "UN_SC",
                Name = "UN Security Council Consolidated List",
                Publisher = "United Nations Security Council",

                // Binding inside the EU, which implements UN designations through its own
                // regulations — not advisory the way a third country's list is.
                LegalEffect = LegalEffect.Binding,
                Format = "XML",
                LandingPageUrl = "https://www.un.org/securitycouncil/content/un-sc-consolidated-list",
                RequiresUserAgent = true,
                IsActive = true,
                ParserKey = "UN_SC",

                // The file is regenerated nightly at 23:00 UTC; an hour later is safe, and
                // an unchanged release costs one 304 with no payload.
                CronExpression = "0 1 * * *",
                MinExpectedRecords = 700,
                CreatedAt = WellKnownIds.SeededAt,
                UpdatedAt = WellKnownIds.SeededAt,
            });
        });

        b.Entity<ImportRun>(e =>
        {
            e.ToTable("import_run");
            e.Property(x => x.StartedAt).HasDefaultValueSql("now()");
            e.Property(x => x.DownloadSha256).HasMaxLength(64).IsFixedLength();
            e.HasIndex(x => new { x.SourceId, x.StartedAt }).IsDescending(false, true);
        });

        b.Entity<SourceSnapshot>(e =>
        {
            e.ToTable("source_snapshot");
            e.Property(x => x.Sha256).HasMaxLength(64).IsFixedLength();
            e.Property(x => x.RetrievedAt).HasDefaultValueSql("now()");
            e.Property(x => x.HttpHeadersJson).HasColumnType("jsonb");
            e.HasIndex(x => new { x.SourceId, x.Sha256 }).IsUnique();
        });

        b.Entity<ImportStagingRecord>(e =>
        {
            e.ToTable("import_staging");
            e.HasKey(x => new { x.ImportRunId, x.SourceRecordKey });
            e.HasOne(x => x.ImportRun).WithMany()
             .HasForeignKey(x => x.ImportRunId).OnDelete(DeleteBehavior.Cascade);
            e.Property(x => x.ContentSha256).HasMaxLength(64).IsFixedLength();
            e.Property(x => x.Payload).HasColumnType("jsonb");
        });

        b.Entity<Designation>(e =>
        {
            e.ToTable("designation", t => t.HasCheckConstraint(
                "designation_validity_ck", "valid_to IS NULL OR valid_to > valid_from"));

            e.Property(x => x.ValidFrom).HasDefaultValueSql("now()");

            // Restrict, not cascade: deleting the artefact a decision was based on must
            // not take the decision with it.
            e.HasOne(x => x.Snapshot).WithMany()
             .HasForeignKey(x => x.SnapshotId).OnDelete(DeleteBehavior.Restrict);
            e.Property(x => x.RawRecord).HasColumnType("jsonb");
            e.Property(x => x.ContentSha256).HasMaxLength(64).IsFixedLength();

            // At most one open revision per source record.
            e.HasIndex(x => new { x.SourceId, x.SourceRecordKey })
             .HasFilter("valid_to IS NULL")
             .IsUnique()
             .HasDatabaseName("designation_current_uq");

            e.HasIndex(x => new { x.SourceId, x.SourceRecordKey });
            e.HasIndex(x => new { x.ValidFrom, x.ValidTo });

            // Cross-list links are looked up by whichever reference the citing publisher
            // used, so both sides of that choice have to be indexed.
            e.HasIndex(x => x.ExternalId).HasFilter("external_id IS NOT NULL");
            e.HasIndex(x => x.PublisherReference).HasFilter("publisher_reference IS NOT NULL");
            e.HasIndex(x => x.RawRecord).HasMethod("gin");
        });

        b.Entity<DesignationName>(e =>
        {
            e.ToTable("designation_name");
            e.HasOne(x => x.Designation).WithMany(x => x.Names)
             .HasForeignKey(x => x.DesignationId).OnDelete(DeleteBehavior.Cascade);

            // Generated by the database, so it can never drift from the original.
            // Depends on sm_normalize_name(), created by raw SQL earlier in the migration.
            e.Property(x => x.NameNormalized)
             .HasComputedColumnSql("sm_normalize_name(name_original)", stored: true);

            // The search hot path.
            e.HasIndex(x => x.NameNormalized)
             .HasMethod("gin")
             .HasOperators("gin_trgm_ops")
             .HasDatabaseName("designation_name_trgm_ix");

            e.HasIndex(x => x.NameDmetaphone).HasFilter("name_dmetaphone IS NOT NULL");
            e.HasIndex(x => x.DesignationId);
            e.ToTable(t => t.HasCheckConstraint(
                "designation_name_weak_source_ck", "weak_source IN ('NONE','SOURCE','DERIVED')"));
        });

        ConfigureChild<DesignationBirth>(b, "designation_birth", x => x.Designation, x => x.Births);
        ConfigureChild<DesignationIdentifier>(b, "designation_identifier", x => x.Designation, x => x.Identifiers);
        ConfigureChild<DesignationAddress>(b, "designation_address", x => x.Designation, x => x.Addresses);
        ConfigureChild<DesignationNationality>(b, "designation_nationality", x => x.Designation, x => x.Nationalities);
        ConfigureChild<DesignationMeasure>(b, "designation_measure", x => x.Designation, x => x.Measures);

        b.Entity<DesignationBirth>(e =>
        {
            e.Property(x => x.CountryIso2).HasMaxLength(2);
            e.ToTable(t =>
            {
                t.HasCheckConstraint("designation_birth_month_ck", "month IS NULL OR month BETWEEN 1 AND 12");
                t.HasCheckConstraint("designation_birth_day_ck", "day IS NULL OR day BETWEEN 1 AND 31");
            });
            e.HasIndex(x => x.Year).HasFilter("year IS NOT NULL");
        });

        // Deterministic match surface, resolved before any fuzzy scoring runs.
        b.Entity<DesignationIdentifier>(e => e.HasIndex(x => new { x.Kind, x.ValueNormalized }));

        b.Entity<DesignationXref>(e =>
        {
            e.ToTable("designation_xref");
            e.HasOne(x => x.Designation).WithMany(x => x.CrossReferences)
             .HasForeignKey(x => x.DesignationId).OnDelete(DeleteBehavior.Cascade);
            e.HasIndex(x => new { x.DesignationId, x.Kind, x.TargetExternalId }).IsUnique();
            e.HasIndex(x => new { x.TargetSourceCode, x.TargetExternalId });
        });

        b.Entity<SanctionProgramme>(e =>
        {
            e.ToTable("sanction_programme");
            e.HasIndex(x => new { x.SourceId, x.Code }).IsUnique();
        });

        b.Entity<LegalInstrument>(e =>
        {
            e.ToTable("legal_instrument");
            e.HasIndex(x => new { x.JurisdictionId, x.InstrumentType, x.InstrumentNumber }).IsUnique();
        });

        // Join tables. The referenced programme or act is NOT cascade-deleted:
        // losing the legal basis of a designation silently is exactly the kind of
        // data loss the audit trail exists to prevent.
        b.Entity<DesignationProgramme>(e =>
        {
            e.ToTable("designation_programme");
            e.HasKey(x => new { x.DesignationId, x.ProgrammeId });
            e.HasOne(x => x.Designation).WithMany(x => x.Programmes)
             .HasForeignKey(x => x.DesignationId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne(x => x.Programme).WithMany()
             .HasForeignKey(x => x.ProgrammeId).OnDelete(DeleteBehavior.Restrict);
            e.HasIndex(x => x.ProgrammeId);
        });

        b.Entity<DesignationLegalInstrument>(e =>
        {
            e.ToTable("designation_legal_instrument", t => t.HasCheckConstraint(
                "designation_legal_instrument_relation_ck",
                "relation IN ('LISTED_BY','AMENDED_BY','DELISTED_BY','IMPLEMENTED_BY')"));
            e.HasKey(x => new { x.DesignationId, x.LegalInstrumentId, x.Relation });
            e.HasOne(x => x.Designation).WithMany(x => x.LegalInstruments)
             .HasForeignKey(x => x.DesignationId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne(x => x.LegalInstrument).WithMany()
             .HasForeignKey(x => x.LegalInstrumentId).OnDelete(DeleteBehavior.Restrict);
            e.HasIndex(x => x.LegalInstrumentId);
        });

        b.Entity<CanonicalSubject>(e =>
        {
            e.ToTable("canonical_subject");
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");
            e.Property(x => x.UpdatedAt).HasDefaultValueSql("now()");
        });

        b.Entity<SubjectDesignationLink>(e =>
        {
            e.ToTable("subject_designation_link", t =>
            {
                t.HasCheckConstraint("subject_link_confidence_ck", "confidence BETWEEN 0 AND 1");
                t.HasCheckConstraint("subject_link_method_ck",
                    "method IN ('MANUAL','DETERMINISTIC','XREF','PROBABILISTIC')");
                t.HasCheckConstraint("subject_link_review_ck",
                    "review_status IN ('AUTO_ACCEPTED','PENDING_REVIEW','CONFIRMED','REJECTED')");
            });
            e.HasKey(x => new { x.CanonicalSubjectId, x.DesignationId });
            e.Property(x => x.Confidence).HasPrecision(5, 4);
            e.Property(x => x.Evidence).HasColumnType("jsonb");
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");
            e.HasIndex(x => x.DesignationId);
            e.HasIndex(x => x.ReviewStatus).HasFilter("review_status = 'PENDING_REVIEW'");
        });

        b.Entity<MatchAlgorithm>(e =>
        {
            e.ToTable("match_algorithm");
            e.HasIndex(x => new { x.Code, x.Version }).IsUnique();
            e.Property(x => x.Parameters).HasColumnType("jsonb");
            e.Property(x => x.ModelSha256).HasMaxLength(64).IsFixedLength();
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");

            // Every screening decision names the algorithm that produced it, so there has
            // to be one from the first query. Rules today; a model becomes a second row
            // with its own version, never an edit to this one — otherwise past decisions
            // start pointing at something that no longer exists.
            e.HasData(new MatchAlgorithm
            {
                Id = WellKnownIds.RulesAlgorithm,
                Code = "RULES",
                Version = "1.0.0",
                NameNormVersion = 1,
                FeatureSetVersion = 1,
                IsActive = true,
                CreatedAt = WellKnownIds.SeededAt,
            });
        });

        b.Entity<ScreeningRequest>(e =>
        {
            e.ToTable("screening_request");
            e.Property(x => x.RequestedAt).HasDefaultValueSql("now()");
            e.Property(x => x.ThresholdUsed).HasPrecision(5, 4);
            e.Property(x => x.QueryIdentifiers).HasColumnType("jsonb");
            e.Property(x => x.QueryCountryIso2).HasMaxLength(2);
            e.HasIndex(x => x.RequestedAt).IsDescending();
        });

        b.Entity<ScreeningCandidate>(e =>
        {
            e.ToTable("screening_candidate");
            e.HasOne(x => x.Request).WithMany(x => x.Candidates)
             .HasForeignKey(x => x.RequestId).OnDelete(DeleteBehavior.Cascade);
            e.Property(x => x.Features).HasColumnType("jsonb");
            e.Property(x => x.Score).HasPrecision(6, 5);
            e.Property(x => x.NameScore).HasPrecision(6, 5);
            e.Property(x => x.SemanticScore).HasPrecision(6, 5);
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");
            e.HasIndex(x => x.DesignationId);
            e.HasIndex(x => x.CreatedAt).IsDescending();

            // What the shadow period is read through: every candidate only the embedding
            // reached, by date.
            e.HasIndex(x => new { x.RetrievedBy, x.CreatedAt });
        });

        b.Entity<EmbeddingModel>(e =>
        {
            e.ToTable("embedding_model");
            e.HasIndex(x => new { x.Code, x.Version }).IsUnique();
            e.Property(x => x.ModelSha256).HasMaxLength(64).IsFixedLength();
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");

            // The model the measurement was made with, so a deployment that turns
            // embeddings on starts from the one row whose numbers are in the README.
            // The digest is Ollama's for bge-m3:latest as pulled on 2026-10-14.
            e.HasData(new EmbeddingModel
            {
                Id = WellKnownIds.BgeM3Model,
                Code = "BGE_M3",
                Version = "1.0.0",
                Provider = "OLLAMA",
                ModelName = "bge-m3",
                Dimensions = 1024,
                ModelSha256 = "7907646426070047a77226ac3e684fbbe8410524f7b4a74d02837e43f2146bab",
                IsActive = true,
                CreatedAt = WellKnownIds.SeededAt,
                Notes = "Measured 2026-10-14: 96.3 % recall@25 on hidden non-Latin spellings, 0 lost against the trigram. tools/SancMeld.Experiments.NameEmbeddings.",
            });
        });

        b.Entity<DesignationNameEmbedding>(e =>
        {
            e.ToTable("designation_name_embedding");
            e.HasKey(x => new { x.NameId, x.ModelId });
            e.HasOne(x => x.Name).WithMany()
             .HasForeignKey(x => x.NameId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne(x => x.Model).WithMany()
             .HasForeignKey(x => x.ModelId).OnDelete(DeleteBehavior.Restrict);
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");

            // The in-memory index loads one model's vectors at a time, and before every
            // search asks for the model's newest vector to learn whether the table moved
            // on — MAX(created_at) off the end of this index instead of a 20 ms scan.
            e.HasIndex(x => new { x.ModelId, x.CreatedAt });
        });

        b.Entity<AdjudicationReason>(e =>
        {
            e.ToTable("adjudication_reason");
            e.HasKey(x => x.Code);
            e.HasData(
                new AdjudicationReason { Code = "DIFFERENT_BIRTH_DATE", Label = "Different date of birth", IsNegative = true },
                new AdjudicationReason { Code = "DIFFERENT_COUNTRY", Label = "Different country / nationality", IsNegative = true },
                new AdjudicationReason { Code = "DIFFERENT_SUBJECT_TYPE", Label = "Subject type mismatch", IsNegative = true },
                new AdjudicationReason { Code = "SURNAME_ONLY", Label = "Only the surname matches", IsNegative = true },
                new AdjudicationReason { Code = "WEAK_ALIAS_ONLY", Label = "Hit is on a weak alias only", IsNegative = true },
                new AdjudicationReason { Code = "COMMON_NAME", Label = "Very common name, no other evidence", IsNegative = true },
                new AdjudicationReason { Code = "IDENTIFIER_MATCH", Label = "Identifier matches", IsNegative = false },
                new AdjudicationReason { Code = "FULL_PROFILE_MATCH", Label = "Name and several identifiers match", IsNegative = false },
                new AdjudicationReason { Code = "CONFIRMED_EXTERNALLY", Label = "Confirmed from an external source", IsNegative = false });
        });

        b.Entity<Adjudication>(e =>
        {
            e.ToTable("adjudication");
            e.HasOne(x => x.Candidate).WithMany()
             .HasForeignKey(x => x.CandidateId).OnDelete(DeleteBehavior.Cascade);
            e.HasOne<AdjudicationReason>().WithMany().HasForeignKey(x => x.ReasonCode);
            e.Property(x => x.DecidedAt).HasDefaultValueSql("now()");
            e.HasIndex(x => x.CandidateId);
            e.HasIndex(x => x.DecidedAt).IsDescending();
        });

        b.Entity<TrainingSample>(e =>
        {
            e.ToTable("training_sample", t => t.HasCheckConstraint(
                "training_sample_origin_ck",
                "origin IN ('PUBLIC_LIST_ALIAS','PUBLIC_LIST_XREF','ADJUDICATION')"));
            e.Property(x => x.Features).HasColumnType("jsonb");
            e.HasIndex(x => new { x.Origin, x.Label });
            e.HasIndex(x => new { x.FeatureSetVersion, x.NameNormVersion });
        });

        b.Entity<Admin>(e =>
        {
            // The two revocation columns and the flag say the same thing, so the database
            // is told they have to agree. A row that is inactive with no revocation date
            // would leave nobody able to answer when access ended.
            e.ToTable("admin", t => t.HasCheckConstraint(
                "admin_revocation_ck",
                "(is_active AND revoked_at IS NULL) OR (NOT is_active AND revoked_at IS NOT NULL)"));

            // Unique on the stored value rather than on lower(email): addresses are
            // lower-cased before they are written, so the two are the same index and this
            // one is the one a lookup can use.
            e.HasIndex(x => x.Email).IsUnique();
            e.Property(x => x.Email).HasMaxLength(320);   // RFC 5321 local-part + domain
            e.Property(x => x.CreatedAt).HasDefaultValueSql("now()");

            // No seed row. An allow list that ships with an entry in it is a back door,
            // and everyone would inherit the same one — the first administrator is added
            // by 'SancMeld.Server admin add', which requires access to the server.
        });
    }

    /// <summary>
    /// Every enum in the model is stored as snake_case text rather than as a native
    /// PostgreSQL enum type. See <see cref="EnumAsSnakeCaseText{TEnum}"/> for why.
    /// Listed one by one on purpose: adding an enum to the domain should be a
    /// deliberate line here, not something a convention silently absorbs.
    /// </summary>
    protected override void ConfigureConventions(ModelConfigurationBuilder c)
    {
        c.Properties<SubjectType>().HaveConversion<EnumAsSnakeCaseText<SubjectType>>();
        c.Properties<LegalEffect>().HaveConversion<EnumAsSnakeCaseText<LegalEffect>>();
        c.Properties<DatePrecision>().HaveConversion<EnumAsSnakeCaseText<DatePrecision>>();
        c.Properties<DesignationStatus>().HaveConversion<EnumAsSnakeCaseText<DesignationStatus>>();
        c.Properties<MeasureType>().HaveConversion<EnumAsSnakeCaseText<MeasureType>>();
        c.Properties<NameType>().HaveConversion<EnumAsSnakeCaseText<NameType>>();
        c.Properties<IdentifierType>().HaveConversion<EnumAsSnakeCaseText<IdentifierType>>();
        c.Properties<AdjudicationDecision>().HaveConversion<EnumAsSnakeCaseText<AdjudicationDecision>>();
        c.Properties<CandidateOrigin>().HaveConversion<EnumAsSnakeCaseText<CandidateOrigin>>();
    }

    /// <summary>Shared configuration for the one-to-many detail tables hanging off a designation.</summary>
    private static void ConfigureChild<TChild>(
        ModelBuilder b,
        string table,
        System.Linq.Expressions.Expression<Func<TChild, Designation?>> parent,
        System.Linq.Expressions.Expression<Func<Designation, IEnumerable<TChild>?>> collection)
        where TChild : class
    {
        b.Entity<TChild>(e =>
        {
            e.ToTable(table);
            e.HasOne(parent).WithMany(collection)
             .HasForeignKey("DesignationId").OnDelete(DeleteBehavior.Cascade);
            e.HasIndex("DesignationId");
        });
    }
}
